import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    def opp(i):
        return history[i][1]

    def me(i):
        return history[i][0]

    # Score bookkeeping
    my_score = 0
    opp_score = 0
    for i in range(n):
        a = me(i)
        b = opp(i)
        if a == 'C' and b == 'C':
            my_score += 3
            opp_score += 3
        elif a == 'C' and b == 'D':
            opp_score += 5
        elif a == 'D' and b == 'C':
            my_score += 5
        else:
            my_score += 1
            opp_score += 1

    opp_defects = 0
    for i in range(n):
        if opp(i) == 'D':
            opp_defects += 1
    opp_c = n - opp_defects

    # Final rounds: exploit based on long-run cooperation rate.
    if n >= 97:
        if opp_c * 4 >= n * 3:
            return 'D'
        if opp_defects * 4 >= n * 3:
            return 'D'
        return 'D' if opp(n - 1) == 'C' else 'C'

    # Near-end: mild exploitation of highly cooperative opponents.
    if n >= 88:
        if opp_c * 10 >= n * 9:
            if rng.random() < 0.8:
                return 'D'
            return 'C'
        if opp_defects * 10 >= n * 9:
            return 'D'

    # Always-defector detection
    if n >= 6 and opp_defects == n:
        return 'D'

    # Punish sustained defection hard
    if n >= 4:
        if opp(n - 1) == 'D' and opp(n - 2) == 'D' and opp(n - 3) == 'D':
            return 'D'

    # Immediate retaliation, but forgive if opponent has been largely cooperative recently.
    if n >= 1 and opp(n - 1) == 'D':
        # Count recent cooperation
        recent = history[-8:] if n >= 8 else history
        rc = sum(1 for a, b in recent if b == 'C')
        rn = len(recent)
        if rn >= 4 and rc * 4 >= rn * 3:
            # Mostly cooperative recently; forgive with some probability
            if rng.random() < 0.7:
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated last.
    # If opponent is nearly always cooperative, exploit now and then but keep gains.
    if n > 25:
        ratio_c = opp_c / float(n)
        if ratio_c >= 0.92:
            if rng.random() < 0.3:
                return 'D'
            return 'C'
        if ratio_c >= 0.75 and my_score < opp_score:
            # We're behind; probe occasionally
            if rng.random() < 0.25:
                return 'D'
            return 'C'
        if ratio_c <= 0.25:
            if rng.random() < 0.85:
                return 'D'
            return 'C'

    # Recent cooperation streak: reciprocate cooperation.
    if n >= 3:
        cstreak = 0
        for i in range(n - 1, -1, -1):
            if opp(i) == 'C':
                cstreak += 1
            else:
                break
        if cstreak >= 6 and n > 20:
            if rng.random() < 0.15:
                return 'D'
            return 'C'

    # Default: cooperate
    return 'C'
